def prepare_lora_batch(
    self,
    cur_uids: Set[Optional[str]],
    lora_adapters: Dict[str, LoRAAdapter],
):

    # Determine adapters to load and adapters to evict
    active_uids: Set[Optional[str]] = set(self.uid_to_buffer_id.keys())
    missing = cur_uids - active_uids
    if missing:
        # Free slots by evicting any adapters not needed by the current batch
        evictable = [uid for uid in active_uids if uid not in cur_uids]
        for uid in evictable:
            buffer_id = self.uid_to_buffer_id.pop(uid)
            self.buffer_id_to_uid[buffer_id] = ""
            # Mark slot as free
            self.free_buffer_ids.append(buffer_id)
            # Clear metadata for evicted slot to avoid stale reads
            if self.lora_ranks_tensor is not None:
                self.lora_ranks_tensor[buffer_id] = 0
            if self.lora_scalings_tensor is not None:
                self.lora_scalings_tensor[buffer_id] = 0

        # Allocate and load all missing adapters
        for uid in missing:
            if not self.free_buffer_ids:
                raise ValueError(
                    "No available buffer slots found. Please ensure the number of active loras is less than max_loras_per_batch."
                )
            buffer_id = self.free_buffer_ids.pop()
            self.load_lora_weight_to_buffer(
                uid, buffer_id, lora_adapters.get(uid, None)
            )
            self.uid_to_buffer_id[uid] = buffer_id
            self.buffer_id_to_uid[buffer_id] = uid

